      ++listToken;
      invalidateSavedView();
      savedTotal.value = null;
      await refresh();
      return true;
    } catch (raw) {
      if (!detached && session === mailboxSessionToken) splitError.value = toMailError(raw);
      return false;
    } finally { if (session === mailboxSessionToken) splitBusy.value = false; }

