    await goTrash(w);
    expect(w.find('[data-test="action-notice-undo"]').exists()).toBe(false);
    await w.get(rowTest('conv-04')).trigger('click'); await flushPromises();
    expect(w.find('[data-test="action-notice-undo"]').exists()).toBe(false);
    for (const letter of ['e', 'E', 'u', 'U', 'z', 's', 'h', 'r', 'j', 'k']) key(letter);
    await flushPromises();
