    expect(ids(box.conversations.value)).toEqual(ids(rows));
    read.mockReset();
    read.mockResolvedValueOnce(snapshot({ conversations: [rows[0]!], nextCursor: 'p2' }))
      .mockRejectedValueOnce({ kind: 'network_unavailable' });
    await box.refresh();
