    vi.spyOn(fake, 'getAccountStatus').mockResolvedValue({ ...oldStatus, account: { ...oldStatus.account!, accountId: 'another-account' } });
    vi.spyOn(fake, 'listConversations').mockResolvedValue({ conversations: [], activity: [] });
    await box.refresh();
